(() => {
'use strict';
const W=960,H=600,canvas=document.getElementById('arena'),ctx=canvas.getContext('2d');
const $=id=>document.getElementById(id);
const ui={intro:$('intro'),upgrade:$('upgrade'),ending:$('ending'),state:$('stateLabel'),hp:$('hpText'),hpBar:$('hpBar'),xp:$('xpText'),xpBar:$('xpBar'),rage:$('rageText'),rageBar:$('rageBar'),clock:$('clock'),wave:$('waveText'),kills:$('killText'),goal:$('goalTitle'),goalText:$('goalText'),relics:$('relics'),toast:$('toast')};
let mode='menu',last=0,keys={},touch={x:0,y:0},joystick={active:false,id:null,cx:0,cy:0},toastTimeout;
let player,enemies=[],sparks=[],particles=[],decor=[],wave=1,waveTime=0,spawnTimer=0,kills=0,run=1,bossSpawned=false,attackTimer=0,attackAnim=0,dodgeTimer=0,dodgeCool=0,level=1,xp=0,xpNeed=40,rage=0,boons=[],elapsed=0,shake=0;
const upgrades=[
 {id:'axe',icon:'🪓',name:'Whetstone',text:'Axe damage +25%.',tip:'Whetstone',apply:()=>player.damage*=1.25},
 {id:'fury',icon:'🔥',name:'Blood Fury',text:'Build rage twice as fast.',tip:'Blood Fury',apply:()=>player.rageRate*=2},
 {id:'heart',icon:'♥',name:'Iron Heart',text:'Max health +30 and heal 30.',tip:'Iron Heart',apply:()=>{player.maxHp+=30;player.hp=Math.min(player.maxHp,player.hp+30)}},
 {id:'boots',icon:'👢',name:'Wolfstride',text:'Move 18% faster.',tip:'Wolfstride',apply:()=>player.speed*=1.18},
 {id:'reach',icon:'✦',name:'Long Reach',text:'Axe reaches 30% farther.',tip:'Long Reach',apply:()=>player.range*=1.3},
 {id:'regen',icon:'🌿',name:'Wild Remedy',text:'Recover 1 heart every 2 sec.',tip:'Wild Remedy',apply:()=>player.regen+=.5},
 {id:'cleave',icon:'⚔',name:'Wide Cleave',text:'Axe arc hits all nearby foes.',tip:'Wide Cleave',apply:()=>player.cleave=true},
 {id:'armor',icon:'🛡',name:'Runed Hide',text:'Take 20% less damage.',tip:'Runed Hide',apply:()=>player.armor=Math.min(.55,player.armor+.2)},
];
function reset(){player={x:W/2,y:H/2,r:17,hp:100,maxHp:100,speed:210,damage:24,range:105,armor:0,regen:0,regenTick:0,cleave:false,rageRate:1,invuln:0};enemies=[];sparks=[];particles=[];wave=1;waveTime=0;spawnTimer=.45;kills=0;bossSpawned=false;attackTimer=.2;attackAnim=0;dodgeTimer=0;dodgeCool=0;level=1;xp=0;xpNeed=40;rage=0;boons=[];elapsed=0;shake=0;mode='playing';ui.intro.classList.add('hidden');ui.upgrade.classList.add('hidden');ui.ending.classList.add('hidden');updateHud();setGoal('NIGHTFALL','The dead are stirring. Hold your ground.');}
function setGoal(a,b){ui.goal.textContent=a;ui.goalText.textContent=b}
function showToast(t){ui.toast.textContent=t;ui.toast.classList.add('show');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>ui.toast.classList.remove('show'),1500)}
function choiceCards(kind){mode='upgrade';ui.upgrade.classList.remove('hidden');if(kind==='level'){ $('upgradeEyebrow').textContent='Renown earned · Level '+level;$('upgradeTitle').innerHTML='CHOOSE YOUR<br><span class="gold">EDGE</span>';$('upgradeDesc').textContent='The old ways reward the living. Choose one boon.';}else{$('upgradeEyebrow').textContent='Dawn breaks · Night '+wave+' survived';$('upgradeTitle').innerHTML='THE FIRE<br><span class="gold">HOLDS</span>';$('upgradeDesc').textContent='Take a moment. The next night will be worse.';}
 const deck=[...upgrades].sort(()=>Math.random()-.5).slice(0,3),cards=$('cards');cards.innerHTML='';deck.forEach(u=>{const b=document.createElement('button');b.className='upgrade-card';b.innerHTML=`<div class="icon">${u.icon}</div><h3>${u.name}</h3><p>${u.text}</p>`;b.onclick=()=>{u.apply();boons.push(u);renderRelics();ui.upgrade.classList.add('hidden');mode='playing';if(kind==='wave'){wave++;waveTime=0;bossSpawned=false;spawnTimer=.6;setGoal(wave===3?'THE WARDEN STIRS':'NIGHTFALL','Night '+wave+' — survive until dawn.');showToast('NIGHT '+wave+' · THE HUNT CONTINUES');}else showToast(u.name.toUpperCase()+' · BOON CLAIMED');updateHud()};cards.appendChild(b)});}
function renderRelics(){ui.relics.innerHTML=boons.length?boons.map(b=>`<div class="relic" data-tip="${b.tip}">${b.icon}</div>`).join(''):'<span style="color:#777466;font-size:11px;align-self:center">None. Yet.</span>'}
function spawnEnemy(type){let side=Math.floor(Math.random()*4),x=side===0?-25:side===1?W+25:Math.random()*W,y=side===2?-25:side===3?H+25:Math.random()*H;let stats={ghoul:{hp:30+wave*5,speed:48+wave*5,damage:9,r:14,color:'#94a387',xp:9},hound:{hp:22+wave*4,speed:82+wave*5,damage:7,r:11,color:'#bd7959',xp:8},brute:{hp:75+wave*13,speed:31+wave*3,damage:16,r:21,color:'#ad5d4c',xp:17},boss:{hp:235,speed:43,damage:21,r:34,color:'#bb6150',xp:55}}[type];enemies.push({x,y,...stats,type,maxHp:stats.hp,hit:0,attack:0,phase:Math.random()*6,dead:false});}
function spawnBoss(){bossSpawned=true;spawnEnemy('boss');setGoal('THE HOLLOW WARDEN','Break its crown. The night ends when it falls.');showToast('THE HOLLOW WARDEN HAS ENTERED THE HUNT');}
function addParticles(x,y,color,n=6,speed=100){for(let i=0;i<n;i++){let a=Math.random()*Math.PI*2,v=Math.random()*speed;particles.push({x,y,vx:Math.cos(a)*v,vy:Math.sin(a)*v,life:.25+Math.random()*.42,max:.67,color,r:2+Math.random()*3})}}
function die(e){e.dead=true;kills++;rage=Math.min(100,rage+7*player.rageRate);sparks.push({x:e.x,y:e.y,r:7,val:e.xp,phase:Math.random()*5});addParticles(e.x,e.y,e.color,9,130);}
function hurt(amount){if(player.invuln>0)return;player.hp-=amount*(1-player.armor);player.invuln=.48;shake=7;addParticles(player.x,player.y,'#e56f5b',8,115);if(player.hp<=0){player.hp=0;endGame(false)}}
function gainXp(v){xp+=v;while(xp>=xpNeed){xp-=xpNeed;level++;xpNeed=Math.round(xpNeed*1.35);choiceCards('level');break}}
function attack(){if(attackTimer>0)return;let target=null,best=player.range;for(let e of enemies){let d=Math.hypot(e.x-player.x,e.y-player.y);if(!e.dead&&d<best){best=d;target=e}}
 if(!target)return;attackTimer=Math.max(.24,.62-(level*.015));attackAnim=.22;let angle=Math.atan2(target.y-player.y,target.x-player.x),didHit=false;for(let e of enemies){if(e.dead)continue;let dx=e.x-player.x,dy=e.y-player.y,d=Math.hypot(dx,dy),da=Math.atan2(dy,dx)-angle;while(da>Math.PI)da-=Math.PI*2;while(da< -Math.PI)da+=Math.PI*2;if(d<player.range&& (e===target||player.cleave)&&Math.abs(da)<(player.cleave?.93:.45)){let dmg=player.damage*(rage>=100?1.7:1);e.hp-=dmg;e.hit=.12;didHit=true;addParticles(e.x,e.y,'#edc879',4,80);if(e.hp<=0)die(e)}}if(didHit){rage=Math.min(100,rage+12*player.rageRate);if(rage>=100)showToast('BLOOD FURY · AXE DAMAGE INCREASED');}}
function dodge(){if(mode!=='playing'||dodgeCool>0)return;let dx=(keys.d||keys.ArrowRight?1:0)-(keys.a||keys.ArrowLeft?1:0)+touch.x,dy=(keys.s||keys.ArrowDown?1:0)-(keys.w||keys.ArrowUp?1:0)+touch.y,l=Math.hypot(dx,dy);if(!l){let e=enemies.find(e=>!e.dead);if(e){dx=player.x-e.x;dy=player.y-e.y;l=Math.hypot(dx,dy)}else{dx=1;dy=0;l=1}}dx/=l;dy/=l;player.x=Math.max(24,Math.min(W-24,player.x+dx*105));player.y=Math.max(24,Math.min(H-24,player.y+dy*105));player.invuln=.48;dodgeTimer=.22;dodgeCool=1.35;addParticles(player.x,player.y,'#d7c58c',13,125);}
function startWave(){if(wave===3&&!bossSpawned&&waveTime>=13)spawnBoss();if(waveTime>=30){if(wave<3){choiceCards('wave')}else if(!enemies.some(e=>e.type==='boss'&&!e.dead)){endGame(true)}}}
function endGame(win){mode=win?'victory':'defeat';ui.ending.classList.remove('hidden');$('endEyebrow').textContent=win?'THE NORTH REMEMBERS':'THE GAME CLAIMS ANOTHER';$('endTitle').innerHTML=win?'A NAME<br><span class="gold">IN IRON</span>':'FALLEN<br><span class="gold">IN THE SNOW</span>';$('endText').textContent=win?'The Hollow Warden is broken. The old king has no more pieces to play. Tonight, the north sings your name.':'The snow takes the warmth from your hands. But even a barbarian can rise again.';$('endStats').textContent=`NIGHTS ${wave}  ·  FOES SLAIN ${kills}  ·  LEVEL ${level}`;ui.state.textContent=win?'VICTOR':'FALLEN';}
function update(dt){if(mode!=='playing')return;elapsed+=dt;waveTime+=dt;player.invuln=Math.max(0,player.invuln-dt);attackTimer-=dt;attackAnim=Math.max(0,attackAnim-dt);dodgeCool=Math.max(0,dodgeCool-dt);rage=Math.max(0,rage-dt*1.8);player.regenTick+=dt;if(player.regenTick>=2){player.regenTick-=2;player.hp=Math.min(player.maxHp,player.hp+player.regen)}
 let mx=(keys.d||keys.ArrowRight?1:0)-(keys.a||keys.ArrowLeft?1:0)+touch.x,my=(keys.s||keys.ArrowDown?1:0)-(keys.w||keys.ArrowUp?1:0)+touch.y,ml=Math.hypot(mx,my);if(ml>1){mx/=ml;my/=ml}player.x=Math.max(20,Math.min(W-20,player.x+mx*player.speed*dt));player.y=Math.max(20,Math.min(H-20,player.y+my*player.speed*dt));if(ml>.1)player.facing=Math.atan2(my,mx);
 spawnTimer-=dt;if(waveTime<30&&spawnTimer<=0){if(enemies.filter(e=>!e.dead&&e.type!=='boss').length<21){let r=Math.random(),type=r<.58?'ghoul':r<.84?'hound':'brute';spawnEnemy(type)}spawnTimer=Math.max(.43,1.08-waveTime*.012)+Math.random()*.42}
 if(wave===3&&!bossSpawned&&waveTime>=13)spawnBoss();for(let e of enemies){if(e.dead)continue;e.phase+=dt*4;e.hit=Math.max(0,e.hit-dt);let dx=player.x-e.x,dy=player.y-e.y,d=Math.hypot(dx,dy)||1;if(d>player.r+e.r+2){e.x+=dx/d*e.speed*dt;e.y+=dy/d*e.speed*dt}else{e.attack-=dt;if(e.attack<=0){hurt(e.damage);e.attack=e.type==='boss'?1.05:1.3}}if(e.type==='boss'&&d<85)e.x-=dx/d*e.speed*dt*.36}
 attack();sparks=sparks.filter(s=>{s.phase+=dt*2;let d=Math.hypot(s.x-player.x,s.y-player.y);if(d<115){s.x+=(player.x-s.x)*dt*2.7;s.y+=(player.y-s.y)*dt*2.7}if(d<player.r+14){gainXp(s.val);addParticles(s.x,s.y,'#edc879',7,70);return false}return true});particles=particles.filter(p=>{p.life-=dt;p.x+=p.vx*dt;p.y+=p.vy*dt;p.vx*=.96;p.vy*=.96;return p.life>0});shake=Math.max(0,shake-dt*24);
 if(wave===3&&waveTime>=30&&!enemies.some(e=>e.type==='boss'&&!e.dead)){endGame(true)}updateHud();}
function updateHud(){ui.hp.textContent=`${Math.ceil(player.hp)} / ${player.maxHp}`;ui.hpBar.style.width=`${Math.max(0,player.hp/player.maxHp*100)}%`;ui.xp.textContent=`${xp} / ${xpNeed}`;ui.xpBar.style.width=`${xp/xpNeed*100}%`;ui.rage.textContent=`${Math.floor(rage)}%`;ui.rageBar.style.width=`${rage}%`;ui.wave.textContent=`${Math.min(wave,3)} / 3`;ui.kills.textContent=String(kills).padStart(2,'0');let remain=Math.max(0,Math.ceil(30-waveTime)),m=Math.floor(remain/60),s=remain%60;ui.clock.textContent=wave===3&&waveTime>=30?'WARDEN':`00:${String(s).padStart(2,'0')}`;ui.state.textContent=mode==='playing'?(rage>=100?'FURY':'HUNTING'):mode.toUpperCase();if(wave===3&&waveTime>=30)setGoal('THE WARDEN','Survive the last hunt. Slay the Hollow Warden.');}

function makeDecor(){let seed=17;const rand=()=>{seed=(seed*9301+49297)%233280;return seed/233280};decor=[];for(let i=0;i<140;i++){let x=rand()*W,y=rand()*H;if(Math.hypot(x-W/2,y-H/2)<185)continue;decor.push({x,y,type:rand()<.44?'stone':'grass',s:3+rand()*12,a:rand()*6.28,shade:Math.floor(rand()*4)})}}
function drawGround(){ctx.fillStyle='#35372b';ctx.fillRect(0,0,W,H);ctx.fillStyle='#3d3e30';ctx.beginPath();ctx.ellipse(W/2,H/2,360,260,0,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#4b4a39';ctx.lineWidth=2;ctx.setLineDash([6,13]);ctx.beginPath();ctx.ellipse(W/2,H/2,344,244,0,0,Math.PI*2);ctx.stroke();ctx.setLineDash([]);
 for(let x=0;x<W;x+=48)for(let y=0;y<H;y+=48){let v=Math.sin(x*12.98+y*7.23)*.5+.5;ctx.fillStyle=v>.62?'#77785c0c':'#11130e08';ctx.fillRect(x+6,y+5,32,28)}
 for(const d of decor){if(d.type==='grass'){ctx.strokeStyle=['#7b785344','#9b8a5544','#747c5844','#535b4644'][d.shade];ctx.lineWidth=1.5;ctx.beginPath();ctx.moveTo(d.x,d.y);ctx.lineTo(d.x+Math.cos(d.a)*d.s,d.y-Math.abs(Math.sin(d.a))*d.s);ctx.stroke()}else{ctx.fillStyle=['#525347','#5d5948','#656052','#4b4e43'][d.shade];ctx.beginPath();ctx.ellipse(d.x,d.y,d.s,d.s*.62,d.a,0,Math.PI*2);ctx.fill();ctx.fillStyle='#ffffff0a';ctx.beginPath();ctx.ellipse(d.x-d.s*.22,d.y-d.s*.2,d.s*.38,d.s*.17,d.a,0,Math.PI*2);ctx.fill()}}
 // pine silhouettes fence the clearing
 for(let i=0;i<13;i++){let x=i*82-20;tree(x,Math.sin(i*3)*25-12,.78+(i%3)*.14);tree(x+27,H-10,.6+(i%3)*.13)}
}
function tree(x,y,s){ctx.save();ctx.translate(x,y);ctx.scale(s,s);ctx.fillStyle='#161b15';ctx.fillRect(-6,-3,12,29);for(let n=0;n<3;n++){ctx.fillStyle=['#20291e','#273023','#303728'][n];ctx.beginPath();ctx.moveTo(0,-82+n*23);ctx.lineTo(-31+n*5,-24+n*19);ctx.lineTo(31-n*5,-24+n*19);ctx.closePath();ctx.fill()}ctx.restore()}
function drawEnemy(e){let bob=Math.sin(e.phase)*2,flash=e.hit>0;ctx.save();ctx.translate(e.x,e.y+bob);ctx.fillStyle='#12130f77';ctx.beginPath();ctx.ellipse(0,e.r*.72,e.r*1.1,e.r*.43,0,0,Math.PI*2);ctx.fill();if(e.type==='boss'){ctx.fillStyle=flash?'#fff1c8':e.color;ctx.beginPath();ctx.arc(0,0,e.r,0,Math.PI*2);ctx.fill();ctx.fillStyle='#72483e';ctx.beginPath();ctx.arc(0,-4,e.r*.71,Math.PI,0);ctx.fill();ctx.fillStyle='#e7bb72';ctx.fillRect(-13,-3,7,5);ctx.fillRect(7,-3,7,5);ctx.strokeStyle='#e7bb72';ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(-20,-20);ctx.lineTo(-33,-39);ctx.lineTo(-7,-27);ctx.moveTo(20,-20);ctx.lineTo(33,-39);ctx.lineTo(7,-27);ctx.stroke();}else{ctx.fillStyle=flash?'#fff1c8':e.color;ctx.beginPath();ctx.ellipse(0,0,e.r*.8,e.r,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#d2c9a8';ctx.beginPath();ctx.arc(-e.r*.35,-e.r*.2,2.1,0,Math.PI*2);ctx.arc(e.r*.35,-e.r*.2,2.1,0,Math.PI*2);ctx.fill();if(e.type==='brute'){ctx.strokeStyle='#543c34';ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(-9,-12);ctx.lineTo(-19,-20);ctx.moveTo(9,-12);ctx.lineTo(19,-20);ctx.stroke()}}
 if(e.hp<e.maxHp){ctx.fillStyle='#171713';ctx.fillRect(-e.r,-e.r-11,e.r*2,4);ctx.fillStyle=e.type==='boss'?'#d37d5a':'#dcb466';ctx.fillRect(-e.r,-e.r-11,e.r*2*Math.max(0,e.hp/e.maxHp),4)}ctx.restore()}
function drawPlayer(){ctx.save();ctx.translate(player.x,player.y);ctx.rotate(player.facing||0);let blink=player.invuln>0&&Math.floor(performance.now()/70)%2===0;ctx.fillStyle='#11120e88';ctx.beginPath();ctx.ellipse(-3,13,22,10,0,0,Math.PI*2);ctx.fill();if(!blink){ctx.fillStyle='#654739';ctx.beginPath();ctx.ellipse(-3,1,14,17,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#c48d66';ctx.beginPath();ctx.arc(8,-5,9,0,Math.PI*2);ctx.fill();ctx.fillStyle='#d5c6a9';ctx.beginPath();ctx.arc(9,-7,8,Math.PI,Math.PI*2);ctx.lineTo(2,-7);ctx.closePath();ctx.fill();ctx.fillStyle='#28251c';ctx.fillRect(11,-7,3,2);ctx.strokeStyle='#c6a66a';ctx.lineWidth=5;ctx.beginPath();ctx.moveTo(0,6);ctx.lineTo(14,15);ctx.stroke();ctx.strokeStyle='#4c473b';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(14,15);ctx.lineTo(22,21);ctx.stroke();ctx.fillStyle='#aeb5a0';ctx.beginPath();ctx.moveTo(21,8);ctx.lineTo(30,13);ctx.lineTo(22,24);ctx.lineTo(18,19);ctx.closePath();ctx.fill();}
 if(attackAnim>0){ctx.strokeStyle='#efd18b';ctx.globalAlpha=attackAnim/.22;ctx.lineWidth=5;ctx.beginPath();ctx.arc(0,0,player.range*.66,-.8,.8);ctx.stroke();ctx.globalAlpha=1}if(rage>=100){ctx.strokeStyle='#dd6f4f';ctx.globalAlpha=.5+Math.sin(elapsed*12)*.2;ctx.lineWidth=2;ctx.beginPath();ctx.arc(0,0,27,0,Math.PI*2);ctx.stroke()}ctx.restore()}
function draw(){ctx.save();if(shake>0)ctx.translate((Math.random()-.5)*shake,(Math.random()-.5)*shake);drawGround();for(let s of sparks){ctx.save();ctx.translate(s.x,s.y+Math.sin(s.phase)*3);ctx.rotate(s.phase);ctx.fillStyle='#efc66c';ctx.shadowColor='#f3bd55';ctx.shadowBlur=15;ctx.beginPath();ctx.moveTo(0,-s.r);ctx.lineTo(s.r*.7,0);ctx.lineTo(0,s.r);ctx.lineTo(-s.r*.7,0);ctx.closePath();ctx.fill();ctx.restore()}for(let e of enemies)if(!e.dead)drawEnemy(e);drawPlayer();for(let p of particles){ctx.globalAlpha=Math.max(0,p.life/p.max);ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x,p.y,p.r,0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1;
 // A quiet moon and weathered arena frame
 ctx.fillStyle='#e0d4ac';ctx.globalAlpha=.22;ctx.beginPath();ctx.arc(866,55,18,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;ctx.restore();}
function loop(t){let dt=Math.min(.034,(t-last)/1000||0);last=t;if(mode==='playing')update(dt);draw();requestAnimationFrame(loop)}
$('start').addEventListener('click',()=>{run++;$('runNum').textContent=String(run).padStart(2,'0');reset()});$('restart').addEventListener('click',()=>{run++;$('runNum').textContent=String(run).padStart(2,'0');reset()});
window.addEventListener('keydown',e=>{let k=e.key.length===1?e.key.toLowerCase():e.key;if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(e.key))e.preventDefault();keys[k]=true;if(e.key===' '&&!e.repeat)dodge()});window.addEventListener('keyup',e=>{let k=e.key.length===1?e.key.toLowerCase():e.key;keys[k]=false});
const joy=$('joy'),knob=$('knob');joy.addEventListener('pointerdown',e=>{e.preventDefault();joy.setPointerCapture(e.pointerId);joystick.active=true;joystick.id=e.pointerId;const r=joy.getBoundingClientRect();joystick.cx=r.left+r.width/2;joystick.cy=r.top+r.height/2;moveJoy(e)});joy.addEventListener('pointermove',e=>{if(joystick.active&&e.pointerId===joystick.id)moveJoy(e)});function moveJoy(e){let dx=e.clientX-joystick.cx,dy=e.clientY-joystick.cy,d=Math.hypot(dx,dy),max=32;if(d>max){dx*=max/d;dy*=max/d}touch.x=dx/max;touch.y=dy/max;knob.style.transform=`translate(${dx}px,${dy}px)`}function endJoy(e){if(e.pointerId===joystick.id){joystick.active=false;touch.x=touch.y=0;knob.style.transform=''}}joy.addEventListener('pointerup',endJoy);joy.addEventListener('pointercancel',endJoy);$('dodge').addEventListener('pointerdown',e=>{e.preventDefault();dodge()});
makeDecor();reset();mode='menu';ui.intro.classList.remove('hidden');ui.state.textContent='READY';setGoal('A wager was made','Endure three nights in the cursed wood.');requestAnimationFrame(loop);
})();

