const upgrades=[
 {id:'axe',icon:'🪓',name:'Whetstone',text:'Axe damage +25%.',tip:'Whetstone',apply:()=>player.damage*=1.25},
 {id:'fury',icon:'🔥',name:'Blood Fury',text:'Build rage twice as fast.',tip:'Blood Fury',apply:()=>player.rageRate*=2},
 {id:'heart',icon:'♥',name:'Iron Heart',text:'Max health +30 and heal 30.',tip:'Iron Heart',apply:()=>{player.maxHp+=30;player.hp=Math.min(player.maxHp,player.hp+30)}},
 {id:'boots',icon:'👢',name:'Wolfstride',text:'Move 18% faster.',tip:'Wolfstride',apply:()=>player.speed*=1.18},
