 :root{--ink:#eeeadf;--muted:#a19d8f;--gold:#e4b85e;--red:#df6857;--green:#91a778;--line:#393a31;--panel:#1a1b17}*{box-sizing:border-box}body{margin:0;background:#10110f;color:var(--ink);font-family:'DM Sans',sans-serif;min-height:100vh;display:flex;align-items:center;justify-content:center;padding:22px;background-image:radial-gradient(ellipse at 50% 5%,#29271f 0,transparent 58%)}button{font:inherit;color:inherit;cursor:pointer}#game{width:min(1200px,100%);display:grid;grid-template-columns:minmax(0,1fr) 286px;gap:14px}.main{min-width:0}.topbar{height:55px;display:flex;align-items:center;justify-content:space-between;padding:0 4px 11px}.brand{display:flex;align-items:center;gap:11px}.brand-mark{width:33px;height:33px;border:1px solid #62533a;color:var(--gold);display:grid;place-items:center;transform:rotate(45deg);font-size:15px}.brand-mark span{transform:rotate(-45deg)}.brand-title{font:600 19px Oswald,sans-serif;letter-spacing:.07em;text-transform:uppercase}.brand-sub{font:10px 'DM Mono',monospace;color:#8f8b7f;letter-spacing:.16em;margin-top:3px}.run-tag{font:10px 'DM Mono',monospace;color:#aaa38f;border:1px solid #3e3b30;padding:7px 10px;letter-spacing:.1em}.arena-frame{position:relative;border:1px solid #4b493c;background:#25261e;box-shadow:0 18px 60px #0008;overflow:hidden}.canvas-wrap{position:relative;line-height:0}canvas{width:100%;height:auto;aspect-ratio:960/600;display:block;touch-action:none}.arena-vignette{pointer-events:none;position:absolute;inset:0;box-shadow:inset 0 0 100px #0a0a08a6,inset 0 -45px 70px #0a0a08a6}.screen{position:absolute;inset:0;z-index:3;display:grid;place-items:center;background:#10110fc9;backdrop-filter:blur(4px);padding:20px}.screen.hidden{display:none}.dialog{width:min(470px,94%);text-align:center;background:#1a1b17f2;border:1px solid #59513f;padding:30px 34px 28px;position:relative;box-shadow:0 18px 55px #0009}.dialog:before,.dialog:after{content:'';position:absolute;width:18px;height:18px;border-color:var(--gold);border-style:solid}.dialog:before{top:7px;left:7px;border-width:1px 0 0 1px}.dialog:after{bottom:7px;right:7px;border-width:0 1px 1px 0}.eyebrow{font:10px 'DM Mono',monospace;color:var(--gold);letter-spacing:.23em;text-transform:uppercase}.dialog h1{font:600 clamp(29px,4vw,47px)/.98 Oswald,sans-serif;text-transform:uppercase;letter-spacing:.035em;margin:12px 0 13px}.dialog p{margin:0 auto 21px;color:#c0bcaf;font-size:13px;line-height:1.6;max-width:365px}.gold{color:var(--gold)}.btn{border:0;background:var(--gold);color:#17150f;padding:13px 22px;min-width:166px;font:700 12px 'DM Mono',monospace;letter-spacing:.14em;text-transform:uppercase;transition:transform .15s,background .15s}.btn:hover{background:#f0cb78;transform:translateY(-2px)}.small-note{color:#898578;font:10px 'DM Mono',monospace;margin-top:13px}.cards{display:flex;gap:9px;margin-top:18px}.upgrade-card{background:#24251e;border:1px solid #494636;padding:13px 12px;text-align:left;flex:1;min-width:0;transition:.18s}.upgrade-card:hover{border-color:var(--gold);background:#302d22;transform:translateY(-3px)}.upgrade-card .icon{font-size:21px}.upgrade-card h3{font:600 15px Oswald,sans-serif;text-transform:uppercase;margin:7px 0 4px}.upgrade-card p{font-size:11px;line-height:1.4;margin:0;color:#a8a394}.aside{display:flex;flex-direction:column;gap:12px;padding-top:55px}.panel{background:linear-gradient(145deg,#20211b,#191a16);border:1px solid #3e3f34;padding:15px 16px}.section-title{font:10px 'DM Mono',monospace;color:#a7a08e;letter-spacing:.17em;text-transform:uppercase;margin-bottom:12px;display:flex;justify-content:space-between}.section-title span{color:#6e6a5e}.stats-row{display:flex;justify-content:space-between;margin:9px 0 5px;font:11px 'DM Mono',monospace;color:#aaa696}.stat-value{color:var(--ink)}.bar{height:7px;background:#35362d;margin-bottom:12px;overflow:hidden}.bar>i{display:block;height:100%;width:100%;background:var(--red);transition:width .18s}.bar.xp>i{background:var(--gold)}.bar.rage>i{background:#bb7657}.meta-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px}.meta{background:#25261f;padding:10px}.meta label{display:block;color:#8e8a7d;font:9px 'DM Mono',monospace;letter-spacing:.12em;text-transform:uppercase}.meta strong{display:block;margin-top:6px;font:600 20px Oswald,sans-serif}.objective{color:#d0ccbf;font-size:12px;line-height:1.5}.objective strong{display:block;font:600 15px Oswald,sans-serif;text-transform:uppercase;margin-bottom:5px;color:#f0eadc}.kill-count{font:500 22px Oswald,sans-serif;color:var(--gold)}.relics{display:flex;gap:6px;min-height:36px}.relic{border:1px solid #56503e;background:#28271f;width:34px;height:34px;display:grid;place-items:center;font-size:17px;position:relative}.relic:after{content:attr(data-tip);display:none;position:absolute;bottom:40px;left:0;background:#111;padding:6px 8px;white-space:nowrap;font:10px 'DM Mono',monospace;z-index:4}.relic:hover:after{display:block}.howto{color:#a7a395;font-size:11px;line-height:1.75}.key{display:inline-grid;place-items:center;min-width:20px;height:19px;border:1px solid #555348;background:#292a23;color:#ded9cc;font:10px 'DM Mono',monospace;padding:0 4px}.tips{border-top:1px solid #37382f;padding-top:10px;margin-top:10px;color:#888577;font-size:10px;line-height:1.5}.bottomline{display:flex;justify-content:space-between;color:#777466;font:9px 'DM Mono',monospace;padding:10px 3px 0;letter-spacing:.1em}.mobile-controls{display:none;position:absolute;inset:auto 10px 10px;justify-content:space-between;align-items:end;z-index:2;pointer-events:none}.joy{width:102px;height:102px;border:1px solid #d5c9a555;border-radius:50%;background:#27241c77;position:relative;pointer-events:auto;touch-action:none}.joy:after{content:'';position:absolute;inset:30px;border:1px solid #d5c9a555;border-radius:50%}.knob{position:absolute;width:34px;height:34px;border-radius:50%;background:#d5c9a577;left:34px;top:34px;z-index:1}.dodge{pointer-events:auto;touch-action:none;border:1px solid #e4b85e99;background:#302a1cbf;color:#f0ca78;border-radius:50%;width:66px;height:66px;font:10px 'DM Mono',monospace}.toast{position:absolute;top:18px;left:50%;transform:translateX(-50%);background:#171811dc;border:1px solid #73603a;color:#e8c66f;font:11px 'DM Mono',monospace;padding:8px 13px;z-index:2;pointer-events:none;opacity:0;transition:opacity .2s}.toast.show{opacity:1}
 @media(max-width:850px){body{padding:10px}#game{grid-template-columns:minmax(0,1fr) 245px;gap:9px}.aside{padding-top:55px}.panel{padding:12px}.brand-title{font-size:16px}}
